using System.IO;
using UnityEditor;
using UnityEngine;

namespace DisasterSafety.EditorTools
{
    /// <summary>
    /// Import rules for everything under Assets/Art: crisp pixel sprites where one art pixel
    /// is 4 UI units at 1920x1080 (25 pixels per unit against the Canvas' 100), plus 9-slice
    /// borders for the UI kit. Files are generated by ArtSource/scripts/build.lua.
    /// </summary>
    public sealed class PixelArtImporter : AssetPostprocessor
    {
        public const string ArtRoot = "Assets/Art/";
        public const float PixelsPerUnit = 25f;

        void OnPreprocessTexture()
        {
            if (!assetPath.StartsWith(ArtRoot)) return;
            var importer = (TextureImporter)assetImporter;
            importer.textureType = TextureImporterType.Sprite;
            importer.spriteImportMode = SpriteImportMode.Single;
            importer.spritePixelsPerUnit = PixelsPerUnit;
            importer.filterMode = FilterMode.Point;
            importer.mipmapEnabled = false;
            importer.textureCompression = TextureImporterCompression.Uncompressed;
            importer.alphaIsTransparency = true;
            importer.wrapMode = TextureWrapMode.Clamp;
            importer.npotScale = TextureImporterNPOTScale.None;
            importer.isReadable = false;
            importer.spriteBorder = BorderFor(Path.GetFileNameWithoutExtension(assetPath));

            var settings = new TextureImporterSettings();
            importer.ReadTextureSettings(settings);
            settings.spriteMeshType = SpriteMeshType.FullRect;
            settings.spriteGenerateFallbackPhysicsShape = false;
            importer.SetTextureSettings(settings);
        }

        /// <summary>9-slice borders in art pixels (left, bottom, right, top). Must match ArtSource/scripts/ui.lua.</summary>
        public static Vector4 BorderFor(string fileName)
        {
            if (fileName.StartsWith("button_")) return new Vector4(9, 9, 9, 9);
            switch (fileName)
            {
                case "panel": return new Vector4(10, 10, 10, 10);
                case "bubble": return new Vector4(7, 7, 7, 7);
                case "input_box": return new Vector4(6, 6, 6, 6);
                default: return Vector4.zero;
            }
        }
    }
}
